        printf("Test passed: Empty array sum is 0\n");
    } else {
        printf("Test failed: Empty array sum not 0\n");
    }

    int arr4[] = {7};
    if (sum_array(arr4, 1) == 7) {
        printf("Test passed: Single element array sum is 7\n");
    } else {
        printf("Test failed: Single element array sum not 7\n");
    }

    return 0;
}

