#include <string.h>

int is_palindrome(const char *s) {
    if (s == NULL) return 0;
    int len = strlen(s);
    if (len == 0) return 1;

    int i = 0;
    int j = len - 1;

    while (i < j) {
        if (s[i] != s[j]) {
            return 0;
        }
        i++;
        j--;
    }
    return 1;
}

