#include <stdio.h>

void swap_integers(int *ptr1, int *ptr2) {
    if (ptr1 == NULL || ptr2 == NULL) {
        return;
    }
    int temp = *ptr1;
    *ptr1 = *ptr2;
    *ptr2 = temp;
}

int main() {
    int a = 5, b = 10;
    printf("Before swap: a = %d, b = %d\n", a, b);
    swap_integers(&a, &b);
    printf("After swap: a = %d, b = %d\n", a, b);

    int x = 7, y = 7;
    printf("Before swap: x = %d, y = %d\n", x, y);
    swap_integers(&x, &y);
    printf("After swap: x = %d, y = %d\n", x, y);

    int m = 1, n = 2;
    for (int i = 0; i < 2; i++) {
        if (i == 0) {
            printf("Before iteration %d: m = %d, n = %d\n", i, m, n);
        } else {
            swap_integers(&m, &n);
            while (m < n) {
                printf("  Inside loop: m = %d, n = %d\n", m, n);
                break;
            }
        }
    }
    return 0;
}

