{
    int data;
    struct Node* next;
};

void add_to_end(struct Node** head, int data)
{
    struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
    if (new_node == NULL)
    {
        perror("Failed to allocate memory for new node");
        return;
    }
    new_node->data = data;
    new_node->next = NULL;

    if (*head == NULL)
    {
        *head = new_node;
        return;
    }

    struct Node* current = *head;
    while (current->next != NULL)
    {
        current = current->next;
    }
    current->next = new_node;
}

// Helper function to print the list (for verification)
void print_list(struct Node* head)
{
    if (head == NULL)
    {
        printf("List is empty.\n");
        return;
    }
    struct Node* current = head;
    while (current != NULL)
    {
        printf("%d -> ", current->data);
        current = current->next;
    }
    printf("NULL\n");
}

// Helper function to free the list (for good practice)
void free_list(struct Node** head)
{
    struct Node* current = *head;
    while (current != NULL)
    {
        struct Node* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main()
{
    struct Node* head = NULL;

    add_to_end(&head, 1);
    add_to_end(&head, 2);
    print_list(head); // Expected: 1 -> 2 -> NULL

    add_to_end(&head, 3);
    print_list(head); // Expected: 1 -> 2 -> 3 -> NULL

    struct Node* empty_head = NULL;
    add_to_end(&empty_head, 5);
    print_list(empty_head); // Expected: 5 -> NULL

    free_list(&head);
    free_list(&empty_head);

    return 0;
}

