#include <stdlib.h> // For abs

struct Time { int hour; int minute; };

static int time_to_minutes(struct Time t) {
    return t.hour * 60 + t.minute;
}

int time_diff_minutes(struct Time t1, struct Time t2) {
    int total_minutes1 = time_to_minutes(t1);
    int total_minutes2 = time_to_minutes(t2);

    if (total_minutes1 > total_minutes2) {
        return abs(total_minutes1 - total_minutes2);
    } else { // Handle the other case for completeness
        int diff = total_minutes2 - total_minutes1;
        return diff;
    }
}

