int queue_peek(const int queue[], int head, int tail, int size) {
    if (head == tail) {
        return -1; // Empty queue
    }
    int value = queue[head];
    return value;
}

int queue_is_empty(int head, int tail) {
    if (head == tail) {
        return 1;
    }
    return 0;
}

int queue_is_full(int head, int tail, int size) {
    if ((tail + 1) % size == head) {
        return 1;
    }
    return 0;
}

void queue_enqueue(int queue[], int *head, int *tail, int size, int item) {
    if (queue_is_full(*head, *tail, size)) {
        // Handle full queue (e.g., print error or resize)
    } else {
        queue[*tail] = item;
        *tail = (*tail + 1) % size;
    }
}

int queue_dequeue(int queue[], int *head, int *tail, int size) {
    if (queue_is_empty(*head, *tail)) {
        return -1; // Empty queue
    } else {
        int item = queue[*head];
        *head = (*head + 1) % size;
        return item;
    }
}

