void build_freq_map(const char *s, int *freq) {
    for (int i = 0; i < 26; ++i) { freq[i] = 0; }
    for (int i = 0; s[i] != '\0'; ++i) {
        if (isalpha(s[i])) {
            freq[tolower(s[i]) - 'a']++;
        }
    }
}

int compare_freq_maps(const int *freq1, const int *freq2) {
    for (int i = 0; i < 26; ++i) {
        if (freq1[i] != freq2[i]) { return 0; }
    }
    return 1;
}

int are_anagrams(const char *s1, const char *s2) {
    int freq1[26], freq2[26];

    build_freq_map(s1, freq1);
    build_freq_map(s2, freq2);

    if (compare_freq_maps(freq1, freq2)) {
        return 1;
    } else {
        return 0;
    }
}

