#include <math.h>

double std_dev(double arr[], int size) {
    if (size <= 1)
    { return 0.0; }

    double sum = 0.0;
    for (int i = 0; i < size; i++)
    { sum += arr[i]; }

    double mean = sum / size;
    double sum_sq_diff = 0.0;

    for (int i = 0; i < size; i++)
    {
        double diff = arr[i] - mean;
        sum_sq_diff += diff * diff;
    }

    double variance = sum_sq_diff / (size - 1);
    return sqrt(variance);
}

