int is_valid_email_simple(const char *email) {
    int at_count = 0;
    const char *at_pos = NULL;

    for (int i = 0; email[i] != '\0'; ++i) {
        if (email[i] == '@') {
            at_count++;
            at_pos = &email[i];
        }
    }

    if (at_count != 1) {
        return 0;
    }

    if (at_pos == NULL) { // Should be caught by at_count != 1, but good for safety
        return 0;
    }

    const char *dot_pos_after_at = NULL;
    int found_dot = 0;
    for (const char *p = at_pos + 1; *p != '\0'; ++p) {
        if (*p == '.') {
            dot_pos_after_at = p;
            found_dot = 1;
            break;
        }
    }

    if (found_dot == 0) {
        return 0;
    }

    // Ensure there's something after the dot (e.g., .com, .org)
    if (dot_pos_after_at != NULL && *(dot_pos_after_at + 1) == '\0') {
        return 0;
    }

    return 1;
}

