#include <string.h>

int char_to_int(char c) {
    if (c >= '0' && c <= '9') { return c - '0'; }
    if (c >= 'A' && c <= 'F') { return c - 'A' + 10; }
    if (c >= 'a' && c <= 'f') { return c - 'a' + 10; }
    return -1; // Should not happen with valid input
}

int str_to_int_base(const char* str, int base) {
    int result = 0;
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        int digit = char_to_int(str[i]);
        if (digit >= base) { return -1; } // Error if digit is out of base range
        result = result * base + digit;
    }
    return result;
}

