int simple_hash(const char* str, int table_size) {
    if (str == NULL || table_size <= 0) { return 0; }
    int hash = 0;
    for (int i = 0; str[i] != '\0'; ++i) {
        hash += str[i];
    }
    return hash % table_size;
}

