#include <string.h>

int count_prefixed_words(const char *str, const char *prefix) {
    int count = 0;
    int prefix_len = strlen(prefix);
    const char *current = str;

    while (*current != '\0') {
        while (*current == ' ') {
            current++;
        }
        if (*current == '\0') break;

        if (strncmp(current, prefix, prefix_len) == 0) {
            if (current[prefix_len] == ' ' || current[prefix_len] == '\0') {
                count++;
            }
        }

        while (*current != ' ' && *current != '\0') {
            current++;
        }
    }
    return count;
}

