#include <stdio.h>

#define STACK_SIZE 5
#define UNDERFLOW_SENTINEL -9999

int stack[STACK_SIZE];
int top = -1;

int push_stack(int value) {
    if (top < STACK_SIZE - 1) {
        top++;
        stack[top] = value;
        return 1;
    } else {
        return 0; // Overflow
    }
}

int pop_stack() {
    if (top >= 0) {
        int popped_value = stack[top];
        top--;
        return popped_value;
    } else {
        return UNDERFLOW_SENTINEL; // Underflow
    }
}

int main() {
    if (push_stack(10)) {
        printf("Pushed 10\n");
    }
    if (push_stack(20)) {
        printf("Pushed 20\n");
    }
    int val = pop_stack();
    if (val != UNDERFLOW_SENTINEL) {
        printf("Popped %d\n", val);
    }
    val = pop_stack();
    if (val != UNDERFLOW_SENTINEL) {
        printf("Popped %d\n", val);
    }
    while (pop_stack() != UNDERFLOW_SENTINEL) {
        // Just keep popping to demonstrate underflow
    }
    if (!push_stack(30)) {
        printf("Failed to push 30 (overflow)\n");
    }
    return 0;
}

