int get_day_of_week(int day, int month, int year)
{
    if (month < 3)
    {
        month += 12;
        year -= 1;
    }

    int k = year % 100;
    int j = year / 100;

    int h = (day + 13 * (month + 1) / 5 + k + k / 4 + j / 4 - 2 * j) % 7;

    if (h < 0)
    {
        h += 7;
    }

    // Adjust Zeller's congruence output (0=Saturday, 1=Sunday, ...) to (0=Sunday, 1=Monday, ...)
    int day_of_week = (h + 6) % 7;

    return day_of_week;
}

