#include <math.h>

// Function to check if three sides can form a valid triangle
int is_valid_triangle(double a, double b, double c) {
    if (a <= 0 || b <= 0 || c <= 0) { return 0; }
    if (a + b <= c || a + c <= b || b + c <= a) { return 0; }
    return 1;
}

// Function to calculate the area of a triangle using Heron's formula
double calculate_triangle_area(double a, double b, double c) {
    if (!is_valid_triangle(a, b, c)) {
        return -1.0;
    }

    double s = (a + b + c) / 2.0;
    double area_squared = s * (s - a) * (s - b) * (s - c);

    // Heron's formula can sometimes result in a tiny negative number due to floating point inaccuracies
    // if the triangle is degenerate. We ensure non-negativity before taking the square root.
    if (area_squared < 0) {
        area_squared = 0;
    }

    return sqrt(area_squared);
}

