int check_password_strength(const char *password) {
    int score = 0;
    int len = 0;
    if (password != NULL) {
        len = strlen(password);
    }

    if (len > 0) { // Initial check for non-empty password
        score += (len > 8) ? 8 : len;
    }

    int has_upper = 0;
    int has_lower = 0;
    int has_digit = 0;
    int has_symbol = 0;

    for (int i = 0; i < len; i++) {
        char c = password[i];
        if (isupper(c)) {
            has_upper = 1;
        } else if (islower(c)) {
            has_lower = 1;
        } else if (isdigit(c)) {
            has_digit = 1;
        } else if (!isalnum(c)) { // isalnum checks for alpha or digit
            has_symbol = 1;
        }
    }

    if (has_upper) {
        score++;
    }
    if (has_lower) {
        score++;
    }
    if (has_digit) {
        score++;
    }
    if (has_symbol) {
        score++;
    }

    return score;
}

