#include <stdio.h>

void bitwise_xor_swap(int *a, int *b) {
    if (a == NULL || b == NULL) {
        return; // Handle null pointers
    }
    if (a == b) {
        return; // No need to swap if pointers are the same
    }

    *a ^= *b;
    *b ^= *a;
    *a ^= *b;
}

int main() {
    int x = 5;
    int y = 10;

    printf("Before swap: x = %d, y = %d\n", x, y);

    bitwise_xor_swap(&x, &y);

    printf("After swap: x = %d, y = %d\n", x, y);

    int p = 7;
    int q = 7;
    bitwise_xor_swap(&p, &q);
    printf("After self-swap: p = %d, q = %d\n", p, q);

    for (int i = 0; i < 2; i++) {
        int val1 = 20 + i;
        int val2 = 30 + i;
        printf("Loop %d - Before swap: val1 = %d, val2 = %d\n", i, val1, val2);
        bitwise_xor_swap(&val1, &val2);
        printf("Loop %d - After swap: val1 = %d, val2 = %d\n", i, val1, val2);
    }

    while (0) { // This block will never execute, but demonstrates brace placement
        printf("This won't be printed.\n");
    }

    return 0;
}

