int binary_to_decimal(const char *binary_string) {
    int decimal = 0;
    int power = 0;
    int len = strlen(binary_string);

    for (int i = len - 1; i >= 0; i--) {
        if (binary_string[i] == '1') {
            decimal += (1 << power);
        }
        power++;
    }
    return decimal;
}

