// Function to reverse a string
void reverseString(char* str) {
    int len = strlen(str);
    for (int i = 0; i < len / 2; i++) {
        char temp = str[i];
        str[i] = str[len - i - 1];
        str[len - i - 1] = temp;
    }
}

char* decimal_to_octal_str(unsigned int decimal, char* buffer) {
    if (decimal == 0) {
        buffer[0] = '0';
        buffer[1] = '\0';
        return buffer;
    }
    int i = 0;
    while (decimal > 0) {
        int remainder = decimal % 8;
        buffer[i++] = remainder + '0';
        decimal /= 8;
    }
    buffer[i] = '\0';
    reverseString(buffer);
    return buffer;
}

