void convert_case(char *str) {
    if (str == NULL) { // Check for null pointer
        return;
    }

    int i = 0;
    while (str[i] != '\0') {
        if (isupper((unsigned char)str[i])) { // Check if character is uppercase
            str[i] = (char)tolower((unsigned char)str[i]);
        } else if (islower((unsigned char)str[i])) { // Check if character is lowercase
            str[i] = (char)toupper((unsigned char)str[i]);
        }
        i++;
    }
}

