    int num_tests = sizeof(test_numbers) / sizeof(test_numbers[0]);
    for (int i = 0; i < num_tests; i++) {
        unsigned int current_num = test_numbers[i];
        int bits = count_set_bits(current_num);
        printf("Number: %u, Set Bits: %d\n", current_num, bits);
    }
    return 0;
}

