void apply_shift(char *c, int shift) {
    if (islower(*c)) {
        *c = 'a' + (*c - 'a' + shift) % 26;
    } else if (isupper(*c)) {
        *c = 'A' + (*c - 'A' + shift) % 26;
    }
}

