#include <stdio.h>

double harmonic_mean(double arr[], int size) {
    if (size == 0) { return 0.0; }
    double sum_reciprocals = 0.0;
    int non_zero_count = 0;

    for (int i = 0; i < size; ++i) {
        if (arr[i] == 0.0) { return 0.0; }
        sum_reciprocals += 1.0 / arr[i];
        non_zero_count++;
    }

    if (non_zero_count == 0) { return 0.0; }
    return (double)non_zero_count / sum_reciprocals;
}

int main() {
    double arr1[] = {1.0, 2.0, 4.0};
    printf("Harmonic mean of {1.0, 2.0, 4.0}: %f\n", harmonic_mean(arr1, 3));

    double arr2[] = {5.0, 5.0, 5.0};
