#include <string.h>

int count_substring(const char *main_str, const char *sub_str) {
    int count = 0;
    int main_len = strlen(main_str);
    int sub_len = strlen(sub_str);

    if (sub_len == 0) {
        return main_len + 1; // Empty string appears before, after, and between every character
    }

    for (int i = 0; i <= main_len - sub_len; ++i) {
        int match = 1; // Assume match initially
        for (int j = 0; j < sub_len; ++j) {
            if (main_str[i + j] != sub_str[j]) {
                match = 0; // Mismatch found
                break; // Exit inner loop
            }
        }
        if (match) {
            count++; // Increment count if full match
        }
    }
    return count;
}

