#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

int is_valid_octet(const char *s, int len) {
    if (len == 0 || len > 3) { return 0; }
    if (len > 1 && s[0] == '0') { return 0; }
    int val = 0;
    for (int i = 0; i < len; i++) {
        if (!isdigit(s[i])) { return 0; }
        val = val * 10 + (s[i] - '0');
    }
    if (val < 0 || val > 255) { return 0; }
    return 1;
}

int is_valid_ipv4(const char *ip_address) {
    int octet_count = 0;
    const char *start = ip_address;
    const char *end = ip_address;

    while (*end != '\0') {
        if (*end == '.') {
            if (!is_valid_octet(start, end - start)) { return 0; }
            octet_count++;
            start = end + 1;
        }
        end++;
    }

    if (!is_valid_octet(start, end - start)) { return 0; }
    octet_count++;

    if (octet_count != 4) { return 0; }

    return 1;
}

