#include <string.h>
#include <math.h>

int char_to_digit(char c) {
    if (c >= '0' && c <= '9') { return c - '0'; }
    if (c >= 'A' && c <= 'F') { return c - 'A' + 10; }
    return -1; // Should not happen with valid input
}

int base_to_decimal(const char *num_str, int base) {
    int decimal_val = 0;
    int power = 0;
    int len = strlen(num_str);

    for (int i = len - 1; i >= 0; i--) {
        char digit_char = num_str[i];
        int digit = char_to_digit(digit_char);
        decimal_val += digit * pow(base, power);
        power++;
    }
    return decimal_val;
}

