char *parse_csv_line(char *line, char *buffer) {
    int i = 0;
    while (line[i] != ',' && line[i] != '\0') {
        buffer[i] = line[i];
        i++;
    }
    buffer[i] = '\0';

    if (line[i] == ',') {
        char *remaining = &line[i + 1];
        while (*remaining && (*remaining == ' ' || *remaining == '\t' || *remaining == '\n' || *remaining == '\r')) {
            remaining++;
        }
        return remaining;
    } else {
        return NULL;
    }
}

