int is_leap(int year) {
    if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
        return 1;
    } else {
        return 0;
    }
}

int get_day_number(int day, int month, int year) {
    int days_in_month[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int day_num = 0;

    if (is_leap(year)) {
        days_in_month[2] = 29;
    }

    for (int i = 1; i < month; i++) {
        day_num += days_in_month[i];
    }
    day_num += day;

    while (day_num > 366) { // Defensive check, should not happen for valid inputs
        day_num -= 366;
    }

    return day_num;
}

