#include <stdio.h>

int count_lines_in_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) { return -1; }

    int count = 0;
    int c;

    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') { count++; }
    }

    // Handle case where file is not empty but doesn't end with a newline
    // And also for a file with a single line not ending with newline
    if (count == 0 && ftell(file) > 0) { count = 1; }
    else if (count > 0) { // If there were newlines, check if the last char was one
        // Seek back to check the last character
        fseek(file, -1, SEEK_END);
        if (fgetc(file) != '\n' && ftell(file) > 0) { count++; }
    }


    fclose(file);
    return count;
}

