#include <math.h>

int is_perfect_square(int num) {
    if (num < 0) {
        return 0;
    }
    if (num == 0) {
        return 1;
    }

    long long low = 1;
    long long high = num;
    while (low <= high) {
        long long mid = low + (high - low) / 2;
        long long square = mid * mid;
        if (square == num) {
            return 1;
        } else if (square < num) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return 0;
}

