#include <stdio.h>

long long factorial_recursive(int n) {
    if (n < 0) { return -1; }
    if (n == 0 || n == 1) { return 1; }
    if (n > 20) { // For values > 20, long long might overflow
        printf("Warning: Input %d might cause overflow with long long.\n", n);
    }
    return n * factorial_recursive(n - 1);
}

int main() {
    int test_cases[] = {5, 0, 1, -1, 10, 21};
    int num_test_cases = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_test_cases; ++i) {
        int n = test_cases[i];
        long long result = factorial_recursive(n);
        if (n < 0) {
            printf("Factorial of %d is: %lld (Error: Negative input)\n", n, result);
        } else {
            printf("Factorial of %d is: %lld\n", n, result);
        }
    }

    return 0;
}

