int generate_random_int(int min, int max) {
    if (min > max) { // Ensure min is not greater than max
        int temp = min;
        min = max;
        max = temp;
    }
    // Seed the random number generator only once
    static int seeded = 0;
    if (!seeded) {
        srand((unsigned int)time(NULL));
        seeded = 1;
    }
    int range = max - min + 1;
    return min + (rand() % range);
}

