double calculate_discounted_price(double original_price, double discount_percentage) {
    if (original_price < 0.0) {
        return -1.0; // Indicate error for negative price
    }
    if (discount_percentage < 0.0 || discount_percentage > 100.0) {
        return -1.0; // Indicate error for invalid discount
    }

    double discount_amount = original_price * (discount_percentage / 100.0);
    double final_price = original_price - discount_amount;

    return final_price;
}

int main() {
    double price1 = calculate_discounted_price(100.0, 10.0);
    printf("Price 1: %.2f\n", price1);

    double price2 = calculate_discounted_price(50.0, 50.0);
    if (price2 >= 0.0) {
