    if (price3 < 0.0) {
        printf("Price 3: Invalid discount.\n");
    }

    double price4 = calculate_discounted_price(-10.0, 20.0);
    while (price4 < 0.0) {
        printf("Price 4: Invalid original price.\n");
        break;
    }

    return 0;
}

