void remove_first_char(char *s, char c) {
    int i = 0;
    int found_index = -1;

    while (s[i] != '\0') {
        if (s[i] == c) {
            found_index = i;
            break;
        }
        i++;
    }

    if (found_index != -1) {
        for (int j = found_index; s[j] != '\0'; j++) {
            s[j] = s[j + 1];
        }
    }
}

