#include <stdio.h>
#include <ctype.h>

int count_words_starting_with(const char *sentence, char start_char) {
    int count = 0;
    int in_word = 0;
    char lower_start_char = tolower((unsigned char)start_char);

    for (int i = 0; sentence[i] != '\0'; ++i) {
        char current_char = sentence[i];
        if (isspace((unsigned char)current_char)) {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            if (tolower((unsigned char)current_char) == lower_start_char) {
                count++;
            }
        }
    }
    return count;
}

int main() {
    printf("Test 1: %d\n", count_words_starting_with("Apple banana orange", 'a'));
    printf("Test 2: %d\n", count_words_starting_with("test TEXT type", 't'));
    printf("Test 3: %d\n", count_words_starting_with("  Another apple  ", 'a'));
    printf("Test 4: %d\n", count_words_starting_with("No matches here", 'z'));
    printf("Test 5: %d\n", count_words_starting_with("", 'a'));
    return 0;
}

