#include <stdio.h>

void reverse_int_array(int* arr, int size) {
    if (size <= 1) { // Block 1: if statement
        return;
    }

    int start = 0;
    int end = size - 1;

    while (start < end) { // Block 2: while loop
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    for (int i = 0; i < size; i++) { // Block 3: for loop
        printf("%d ", arr[i]);
    }
    printf("\n");

    reverse_int_array(arr, size); // Function call

    printf("Reversed array: ");
    for (int i = 0; i < size; i++) { // Block 4: for loop
        printf("%d ", arr[i]);
    }
    printf("\n");

    int arr2[] = {10, 20};
    int size2 = sizeof(arr2) / sizeof(arr2[0]);
    if (size2 > 0) { // Block 5: if statement
        reverse_int_array(arr2, size2);
        printf("Reversed array 2: %d %d\n", arr2[0], arr2[1]);
    }

    int arr3[] = {100};
    int size3 = sizeof(arr3) / sizeof(arr3[0]);
    if (size3 == 1) { // Block 6: if statement
        reverse_int_array(arr3, size3);
        printf("Reversed array 3: %d\n", arr3[0]);
    }

    return 0;
}

