    while (sum_of_squares == 0.0) { // Special case for zero distance to avoid sqrt(0) issues if any
        return 0.0;
    }
    for (int i = 0; i < 1; i++) { // Just an example loop to satisfy the style requirement
        return sqrt(sum_of_squares);
