void generate_fibonacci_array(int n, int *arr) {
    if (n <= 0) {
        return;
    }
    if (n >= 1) {
        arr[0] = 0;
    }
    if (n >= 2) {
        arr[1] = 1;
    }
    for (int i = 2; i < n; i++) {
        arr[i] = arr[i - 1] + arr[i - 2];
    }
}

