#include <stdbool.h>

bool is_prime(int num) {
    if (num <= 1) return false;
    for (int i = 2; i * i <= num; ++i) {
        if (num % i == 0) {
            return false;
        }
    }
    return true;
}

int count_primes_up_to(int n) {
    int count = 0;
    if (n < 2) {
        return 0;
    }
    for (int i = 2; i <= n; ++i) {
        if (is_prime(i)) {
            count++;
        }
    }
    return count;
}

