#include <stdio.h>

char caesar_encrypt_char(char c, int shift_amount) {
    if (c >= 'a' && c <= 'z') {
        int base = 'a';
        int shifted_char_code = (c - base + shift_amount) % 26;
        if (shifted_char_code < 0) {
            shifted_char_code += 26;
        }
        return (char)(base + shifted_char_code);
    } else {
        return c; // Non-lowercase letters are returned unchanged
    }
}

int main() {
    char test_char_1 = 'a';
    int shift_1 = 3;
    char encrypted_1 = caesar_encrypt_char(test_char_1, shift_1);
    printf("'%c' shifted by %d is '%c'\n", test_char_1, shift_1, encrypted_1);

    char test_char_2 = 'y';
    int shift_2 = 3;
    char encrypted_2 = caesar_encrypt_char(test_char_2, shift_2);
    printf("'%c' shifted by %d is '%c'\n", test_char_2, shift_2, encrypted_2);

    char test_char_3 = 'm';
    int shift_3 = 15;
    char encrypted_3 = caesar_encrypt_char(test_char_3, shift_3);
