#include <stdio.h>

double average_word_length(const char *sentence) {
    int total_length = 0;
    int word_count = 0;
    int in_word = 0;

    for (int i = 0; sentence[i] != '\0'; i++) {
        if (sentence[i] != ' ') {
            if (!in_word) {
                word_count++;
                in_word = 1;
            }
            total_length++;
        } else {
            in_word = 0;
        }
    }

    if (word_count == 0) {
        return 0.0;
    } else {
        return (double)total_length / word_count;
    }
}

int main() {
    printf("%.1f\n", average_word_length("hello world"));
    printf("%.1f\n", average_word_length("a bb ccc"));
    printf("%.1f\n", average_word_length(""));
    printf("%.1f\n", average_word_length("  "));
    return 0;
}

