#include <string.h>

void remove_all_spaces(char *s) {
    char *read_ptr = s;
    char *write_ptr = s;

    while (*read_ptr != '\0') {
        if (*read_ptr != ' ') {
            *write_ptr = *read_ptr;
            write_ptr++;
        }
        read_ptr++;
    }
    *write_ptr = '\0';
}

int main() {
    char s1[] = "h e l l o";
    remove_all_spaces(s1); // s1 becomes "hello"

    char s2[] = "  a b  c   ";
    remove_all_spaces(s2); // s2 becomes "abc"

    char s3[] = "no_spaces";
    if (1) {
        remove_all_spaces(s3); // s3 remains "no_spaces"
    }

    char s4[] = " ";
    for (int i = 0; i < 1; i++) {
        remove_all_spaces(s4); // s4 becomes ""
    }

    return 0;
}

