long long factorialIterative(int n) {
    long long result = 1;
    if (n < 0) { // Check for negative input
        return -1; // Or handle error appropriately
    }
    for (int i = 1; i <= n; i++) {
        result *= i;
    }
    return result;
}

int main() {
    int num1 = 5;
    long long fact1 = factorialIterative(num1);
    printf("Factorial of %d is %lld\n", num1, fact1);

    int num2 = 0;
    long long fact2 = factorialIterative(num2);
    printf("Factorial of %d is %lld\n", num2, fact2);

    int num3 = 10;
    if (num3 >= 0) {
        long long fact3 = factorialIterative(num3);
        printf("Factorial of %d is %lld\n", num3, fact3);
    } else {
        printf("Cannot calculate factorial for negative number.\n");
    }

    int num4 = -3;
    long long fact4 = factorialIterative(num4);
    if (fact4 == -1) {
        printf("Error: Factorial of a negative number is undefined.\n");
    }

    return 0;
}

