#include <stdio.h>

void swapIntegers(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int main() {
    int x = 5;
    int y = 10;

    printf("Before swap: x = %d, y = %d\n", x, y);
    swapIntegers(&x, &y);
    printf("After swap: x = %d, y = %d\n", x, y);

    int p = 1;
    int q = 1;

    if (p == q) {
        printf("Before swap: p = %d, q = %d\n", p, q);
        swapIntegers(&p, &q);
        printf("After swap: p = %d, q = %d\n", p, q);
    } else {
        printf("P and Q are different.\n");
    }

    for (int i = 0; i < 1; i++) {
        int val1 = 20 + i;
        int val2 = 30 + i;
        while (val1 < val2) {
            printf("Before swap: val1 = %d, val2 = %d\n", val1, val2);
            swapIntegers(&val1, &val2);
            printf("After swap: val1 = %d, val2 = %d\n", val1, val2);
            break;
        }
    }

    return 0;
}

