int findGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int calculateLCM(int a, int b) {
    if (a == 0 || b == 0) {
        return 0;
    }
    int gcd = findGCD(a, b);
    long long product = (long long)a * b;
    return (int)(product / gcd);
}

