void reverseString(char *str) {
    int len = strlen(str);
    int i;
    for (i = 0; i < len / 2; i++) {
        char temp = str[i];
        str[i] = str[len - 1 - i];
        str[len - 1 - i] = temp;
    }
}

void decimalToBinary(int decimal, char *binaryStr) {
    if (decimal == 0) {
        strcpy(binaryStr, "0");
        return;
    }

    int i = 0;
    while (decimal > 0) {
        binaryStr[i++] = (decimal % 2) + '0';
        decimal /= 2;
    }
    binaryStr[i] = '\0';
    reverseString(binaryStr);
}

