#include <string.h>

int findWord(const char *text, const char *word) {
    int textLen = strlen(text);
    int wordLen = strlen(word);

    if (wordLen == 0) {
        return 0;
    }

    for (int i = 0; i <= textLen - wordLen; i++) {
        int j;
        for (j = 0; j < wordLen; j++) {
            if (text[i + j] != word[j]) {
                break;
            }
        }
        if (j == wordLen) {
            return i;
        }
    }
    return -1;
}

