#include <stdio.h>

int calculateDivisorSum(int num) {
    int sum = 1;
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            sum += i;
            if (i * i != num) {
                sum += num / i;
            }
        }
    }
    return sum;
}

int isPerfectNumber(int n) {
    if (n <= 1) {
        return 0;
    }
    int sumOfDivisors = calculateDivisorSum(n);
    if (sumOfDivisors == n) {
        return 1;
    } else {
        return 0;
    }
}

