#include <string.h>

void removeFirstSubstring(char *mainStr, const char *subStr) {
    char *occurrence = strstr(mainStr, subStr);
    if (occurrence != NULL) {
        size_t subLen = strlen(subStr);
        size_t mainLen = strlen(mainStr);
        char *endOfMain = mainStr + mainLen;
        char *startOfShift = occurrence + subLen;
        while (startOfShift <= endOfMain) {
            *occurrence = *startOfShift;
            occurrence++;
            startOfShift++;
        }
    }
}

