// Function to calculate the sum of digits for a single number
int sumDigits(int num) {
    int sum = 0;
    while (num != 0) {
        sum += num % 10;
        num /= 10;
    }
    return sum;
}

// Function to calculate the sum of digits for each number in an array
// and then sum up these individual sums.
int sumOfAllDigitsInArray(int arr[], int size) {
    int totalSum = 0;
    for (int i = 0; i < size; i++) {
        totalSum += sumDigits(arr[i]);
    }
    return totalSum;
}

// Example usage
int main() {
    int arr1[] = {12, 345};
    int size1 = sizeof(arr1) / sizeof(arr1[0]);
    int result1 = sumOfAllDigitsInArray(arr1, size1);
    printf("Result 1: %d\n", result1); // Expected: 15

    int arr2[] = {7, 10};
    int size2 = sizeof(arr2) / sizeof(arr2[0]);
    int result2 = sumOfAllDigitsInArray(arr2, size2);
    printf("Result 2: %d\n", result2); // Expected: 8

    return 0;
}

