int isValidEmail(const char* email) {
    int atCount = 0;
    int atIndex = -1;
    int len = strlen(email);
    for (int i = 0; i < len; i++)
    {
        if (email[i] == '@')
        {
            atCount++;
            atIndex = i;
        }
    }
    if (atCount != 1)
    {
        return 0;
    }
    if (atIndex == 0 || atIndex == len - 1)
    {
        return 0;
    }
    int dotAfterAt = 0;
    for (int i = atIndex + 1; i < len; i++)
    {
        if (email[i] == '.')
        {
            dotAfterAt = 1;
            break;
        }
    }
    if (!dotAfterAt)
    {
        return 0;
    }
    return 1;
}

