int isPalindromeCaseInsensitive(const char* str)
{
    int len = strlen(str);
    int left = 0;
    int right = len - 1;

    while (left < right)
    {
        if (tolower(str[left]) != tolower(str[right]))
        {
            return 0;
        }
        left++;
        right--;
    }
    return 1;
}

