#include <stdio.h>

int reverseInteger(int n)
{
    int reversedNum = 0;
    int sign = 1;

    if (n < 0) {
        sign = -1;
        n = -n;
    }

    while (n > 0) {
        int digit = n % 10;
        reversedNum = reversedNum * 10 + digit;
        n /= 10;
    }

    return reversedNum * sign;
}

int main()
{
    printf("Reversed 1234: %d\n", reverseInteger(1234));
    printf("Reversed -567: %d\n", reverseInteger(-567));
    printf("Reversed 0: %d\n", reverseInteger(0));
    printf("Reversed 9: %d\n", reverseInteger(9));
    printf("Reversed -10: %d\n", reverseInteger(-10));
    return 0;
}

