    {
        if (dest != NULL && destSize > 0)
        {
            dest[0] = '\0';
        }
        return dest;
    }

    int i = 0;
    while (source[i] == ' ')
    {
        i++;
    }

    int j = 0;
    while (source[i] != '\0' && source[i] != ' ' && j < destSize - 1)
    {
        dest[j] = source[i];
        i++;
        j++;
    }

    dest[j] = '\0';
    return dest;
}

