{
    printf("2000 is a leap year: %d\n", isLeapYear(2000));
    printf("1900 is a leap year: %d\n", isLeapYear(1900));
    printf("2024 is a leap year: %d\n", isLeapYear(2024));
    printf("2023 is a leap year: %d\n", isLeapYear(2023));
    int testYears[] = {1600, 1700, 1800, 1900, 2000, 2100, 2400};
    int i;
    for (i = 0; i < sizeof(testYears) / sizeof(testYears[0]); i++)
    {
        int currentYear = testYears[i];
        if (isLeapYear(currentYear))
        {
            printf("%d is a leap year.\n", currentYear);
        }
        else
        {
            printf("%d is not a leap year.\n", currentYear);
        }
    }
    return 0;
}

