#include <stdbool.h>

int parseIntSafe(const char* str, int* result) {
    if (str == NULL || result == NULL) {
        return 0;
    }

    int num = 0;
    bool isNegative = false;
    int i = 0;

    if (str[0] == '-') {
        isNegative = true;
        i++;
    }

    while (str[i] != '\0') {
        char c = str[i];
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
        } else {
            return 0;
        }
        i++;
    }

    if (isNegative) {
        *result = -num;
    } else {
        *result = num;
    }

    return 1;
}

