int appendLineToFile(const char* filename, const char* line)
{
    FILE *fp;
    fp = fopen(filename, "a");
    if (fp == NULL)
    {
        return 0;
    }

    int result = fputs(line, fp);
    if (result == EOF)
    {
        fclose(fp);
        return 0;
    }

    result = fputc('\n', fp);
    if (result == EOF)
    {
        fclose(fp);
        return 0;
    }

    if (fclose(fp) == EOF)
    {
        return 0;
    }

    return 1;
}

