char* toTitleCase(char* str)
{
    int capitalizeNext = 1;
    for (int i = 0; str[i] != '\0'; i++)
    {
        if (isspace((unsigned char)str[i]))
        {
            capitalizeNext = 1;
        }
        else
        {
            if (capitalizeNext)
            {
