#include <string.h>

int findSubstringIndex(const char* mainStr, const char* subStr) {
    if (!mainStr || !subStr) {
        return -1;
    }

    int mainLen = strlen(mainStr);
    int subLen = strlen(subStr);

    if (subLen == 0) {
        return 0;
    }

    if (subLen > mainLen) {
        return -1;
    }

    for (int i = 0; i <= mainLen - subLen; i++) {
        int j;
        for (j = 0; j < subLen; j++) {
            if (mainStr[i + j] != subStr[j]) {
                break;
            }
        }
        if (j == subLen) {
            return i;
        }
    }

    return -1;
}

