#include <stdio.h>

double convertTemperature(double fahrenheit) {
    double celsius;
    celsius = (fahrenheit - 32.0) * 5.0 / 9.0;
    return celsius;
}

double fahrenheitToCelsius(double fahrenheit)
{
    if (fahrenheit < -459.67) { // Absolute zero in Fahrenheit
        return -999.0; // Indicate error or invalid input
    }

    double result = convertTemperature(fahrenheit);

    return result;
}

int main()
{
    double tempF1 = 32.0;
    double tempC1 = fahrenheitToCelsius(tempF1);
    printf("%.2f Fahrenheit is %.2f Celsius\n", tempF1, tempC1);

    double tempF2 = 212.0;
    double tempC2 = fahrenheitToCelsius(tempF2);
    printf("%.2f Fahrenheit is %.2f Celsius\n", tempF2, tempC2);

    for (double i = 0.0; i <= 100.0; i += 25.0) {
        printf("%.2f F -> %.2f C\n", i, fahrenheitToCelsius(i));
    }

    return 0;
}

