int areAnagrams(const char* str1, const char* str2)
{
    int counts[26] = {0};
    int i = 0;

    while (str1[i] != '\0')
    {
        counts[str1[i] - 'a']++;
        i++;
    }

    i = 0;
    while (str2[i] != '\0')
    {
        counts[str2[i] - 'a']--;
