void swapArrayElements(int* arr, int idx1, int idx2)
{
    if (arr == NULL)
    {
        return;
    }

    int temp = arr[idx1];
    arr[idx1] = arr[idx2];
    arr[idx2] = temp;
}

void printArray(int* arr, int size)
{
    printf("{");
    for (int i = 0; i < size; i++)
    {
        printf("%d", arr[i]);
        if (i < size - 1)
        {
            printf(", ");
        }
    }
    printf("}\n");
}

int main()
{
    int a[] = {1, 2, 3};
    int size_a = sizeof(a) / sizeof(a[0]);

    printf("Original array a: ");
    printArray(a, size_a);

    swapArrayElements(a, 0, 2);
    printf("Array a after swapping elements at indices 0 and 2: ");
    printArray(a, size_a);

    int b[] = {5, 10};
    int size_b = sizeof(b) / sizeof(b[0]);

    printf("Original array b: ");
    printArray(b, size_b);

    swapArrayElements(b, 0, 1);
    printf("Array b after swapping elements at indices 0 and 1: ");
    printArray(b, size_b);

    return 0;
}

