int sumEvenInRange(int start, int end) {
    int sum = 0;
    int currentNum = start;

    if (start > end) {
        int temp = start;
        start = end;
        end = temp;
    }

    if (start % 2 != 0) {
        start++;
    }

    for (currentNum = start; currentNum <= end; currentNum += 2) {
        sum += currentNum;
    }

    return sum;
}

// Example usage (main function for testing)
int main() {
    printf("Sum of even numbers in [1, 10]: %d\n", sumEvenInRange(1, 10));
    printf("Sum of even numbers in [7, 10]: %d\n", sumEvenInRange(7, 10));
    printf("Sum of even numbers in [10, 1]: %d\n", sumEvenInRange(10, 1));
    printf("Sum of even numbers in [2, 2]: %d\n", sumEvenInRange(2, 2));
    printf("Sum of even numbers in [3, 3]: %d\n", sumEvenInRange(3, 3));
