#include <stdio.h>

int customAtoi(const char* str) {
    int result = 0;
    int sign = 1;
    int i = 0;

    if (str[0] == '-') {
        sign = -1;
        i++;
    } else if (str[0] == '+') {
        i++;
    }

    while (str[i] != '\0') {
        result = result * 10 + (str[i] - '0');
        i++;
    }

    return result * sign;
}

// Helper function to test customAtoi
void testAtoi(const char* input, int expected) {
    int actual = customAtoi(input);
    if (actual == expected) {
        printf("Test passed for \"%s\": Expected %d, Got %d\n", input, expected, actual);
    } else {
        printf("Test FAILED for \"%s\": Expected %d, Got %d\n", input, expected, actual);
    }
}

int main() {
    testAtoi("123", 123);
    testAtoi("-45", -45);
    testAtoi("0", 0);
    testAtoi("9999", 9999);
    testAtoi("-1", -1);
    testAtoi("+100", 100);
    return 0;
}

