int enqueue(int* queue, int* head, int* tail, int capacity, int value) {
    if (*tail == capacity && *head == 0)
    {
        return 0; // Queue is full
    }

    if (*tail == capacity && *head != 0)
    {
        // Wrap around if space available at the beginning
        if (*head <= 0)
        {
            return 0; // This case should ideally not happen if head is managed correctly
        }
        else
        {
            *tail = 0;
        }
    }

    if (*tail == *head -1 && *head != 0)
    {
        return 0; // Queue is full (circularly)
    }

    queue[*tail] = value;
    (*tail)++;
    if (*tail == capacity && *head != 0)
    {
        *tail = 0; // Wrap around if not full
    }

    if (*tail == capacity && *head == 0)
    {
        if (capacity > 0)
        {
            // The queue is full, but we just added an element. Reset tail to 0 only if head is not 0.
            // If head is 0 and tail is capacity, it means it was full to begin with, so we should have returned 0.
        }
    }

    return 1;
}

