#include <string.h>

char findMostFrequentChar(const char* str)
{
    int counts[256] = {0};
    int maxCount = 0;
    char mostFrequent = 0;

    for (int i = 0; str[i] != '\0'; i++)
    {
        unsigned char c = (unsigned char)str[i];
        counts[c]++;
    }

    for (int i = 0; i < 256; i++)
    {
        if (counts[i] > maxCount)
        {
            maxCount = counts[i];
            mostFrequent = (char)i;
        }
        else if (counts[i] == maxCount)
        {
            if (mostFrequent == 0 || (char)i < mostFrequent)
            {
                mostFrequent = (char)i;
            }
        }
    }
    return mostFrequent;
}

