int calculateTriangleNumber(int n)
{
    int sum = 0;
    if (n < 0)
    {
        return 0; // Triangle numbers are for non-negative integers
    }
    for (int i = 1; i <= n; i++)
    {
        sum += i;
    }
    return sum;
}

int main()
{
    // Test cases
    int result1 = calculateTriangleNumber(1);
    printf("Triangle number for 1: %d\n", result1);

    int result2 = calculateTriangleNumber(5);
    printf("Triangle number for 5: %d\n", result2);

    int result3 = calculateTriangleNumber(0);
    printf("Triangle number for 0: %d\n", result3);

    int result4 = calculateTriangleNumber(10);
    if (result4 == 55)
    {
        printf("Test for 10 passed.\n");
