#include <string.h>

char* removeLeadingZeros(char* str)
{
    if (str == NULL)
    {
        return NULL;
    }

    char* ptr = str;
    while (*ptr == '0' && *(ptr + 1) != '\0')
    {
        ptr++;
    }

    if (*ptr == '0' && *(ptr + 1) == '\0' && ptr != str)
    {
        *str = '0';
        *(str + 1) = '\0';
        return str;
    }

    if (ptr != str)
    {
        char* current = str;
        while (*ptr != '\0')
        {
            *current = *ptr;
            current++;
            ptr++;
        }
        *current = '\0';
    }

    return str;
}

