double calculateWeightedAverage(const double* values, const double* weights, int size)
{
    double sumWeightedValues = 0.0;
    double sumWeights = 0.0;
    if (size <= 0)
    {
        return 0.0;
    }
    for (int i = 0; i < size; i++)
    {
        sumWeightedValues += values[i] * weights[i];
        sumWeights += weights[i];
    }
    if (sumWeights == 0.0)
    {
        return 0.0;
    }
    double result = sumWeightedValues / sumWeights;
    return result;
}

