int isValidHexColor(const char* hexStr)
{
    if (hexStr == NULL)
    {
        return 0;
    }

    if (strlen(hexStr) != 6)
    {
        return 0;
    }

    for (int i = 0; i < 6; i++)
    {
        char c = hexStr[i];
        if (!((c >= '0' && c <= '9') ||
              (c >= 'a' && c <= 'f') ||
              (c >= 'A' && c <= 'F')))
        {
            return 0;
        }
    }
    return 1;
}

