char* rotateStringLeft(char* str, int n)
{
    if (str == NULL || *str == '\0') { return str; }
    int len = strlen(str);
    if (len == 0) { return str; }

    n %= len;
    if (n == 0) { return str; }

    reverse(str, str + n - 1);
    reverse(str + n, str + len - 1);
    reverse(str, str + len - 1);

    return str;
}

