void reverse(char* s
) {
    int i, j;
    char c;
    for (i = 0, j = strlen(s) - 1; i < j; i++, j--
    ) {
        c = s[i];
        s[i] = s[j];
        s[j] = c;
    }
}

char* decToBaseN(int num, int base, char* buffer, int bufferSize
) {
    if (base < 2 || base > 16 || bufferSize <= 0
    ) {
        if (bufferSize > 0
        ) {
            buffer[0] = '\0';
        }
        return buffer;
    }

    int i = 0;
    int isNegative = 0;

    if (num == 0
    ) {
        buffer[i++] = '0';
        buffer[i] = '\0';
        return buffer;
    }

    if (num < 0
    ) {
        isNegative = 1;
        num = -num;
    }

    while (num > 0 && i < bufferSize - 1
    ) {
        int remainder = num % base;
        if (remainder < 10
        ) {
            buffer[i++] = remainder + '0';
        } else
        {
            buffer[i++] = remainder - 10 + 'A';
        }
        num /= base;
    }

    if (isNegative && i < bufferSize - 1
    ) {
        buffer[i++] = '-';
    }

    buffer[i] = '\0';
    reverse(buffer);
    return buffer;
}

