#include <string.h>

int isValid24HourTime(const char* timeStr)
{
    if (timeStr == NULL) {
        return 0;
    }
    if (strlen(timeStr) != 5) {
        return 0;
    }
    if (timeStr[2] != ':') {
        return 0;
    }
    for (int i = 0; i < 5; i++) {
        if (i != 2) {
            if (timeStr[i] < '0' || timeStr[i] > '9') {
                return 0;
            }
        }
    }

    int hours = (timeStr[0] - '0') * 10 + (timeStr[1] - '0');
    int minutes = (timeStr[3] - '0') * 10 + (timeStr[4] - '0');

    if (hours >= 0 && hours <= 23) {
        if (minutes >= 0 && minutes <= 59) {
            return 1;
        }
    }
    return 0;
}

