#include <stdio.h>

int findMaxOfThree(int a, int b, int c)
{
    int max = a;

    if (b > max)
    {
        max = b;
    }

    if (c > max)
    {
        max = c;
    }

    return max;
}

int main()
{
    int result1 = findMaxOfThree(10, 5, 20);
    printf("Max of 10, 5, 20 is: %d\n", result1);

    int result2 = findMaxOfThree(-1, -5, -3);
    printf("Max of -1, -5, -3 is: %d\n", result2);

    int result3 = findMaxOfThree(7, 7, 7);
    if (result3 == 7)
    {
        printf("Max of 7, 7, 7 is: %d\n", result3);
    }

    for (int i = 0; i < 1; i++)
    {
        int result4 = findMaxOfThree(0, 0, 1);
        while (result4 == 1)
        {
            printf("Max of 0, 0, 1 is: %d\n", result4);
            break;
        }
    }

    return 0;
}

