#include <stdio.h>

int dequeue(int *queue, int *front, int size)
{
    if (*front >= size)
    {
        return -1;
    }

    int element = queue[*front];
    (*front)++;
    return element;
}

int main()
{
    int q1[] = {10, 20, 30};
    int front1 = 0;
    int size1 = 3;

    printf("Dequeued: %d\n", dequeue(q1, &front1, size1));
    printf("New front: %d\n", front1);

    printf("Dequeued: %d\n", dequeue(q1, &front1, size1));
    printf("New front: %d\n", front1);

    printf("Dequeued: %d\n", dequeue(q1, &front1, size1));
    printf("New front: %d\n", front1);

    printf("Dequeued: %d\n", dequeue(q1, &front1, size1));
    printf("New front: %d\n", front1);

    int q2[] = {};
    int front2 = 0;
    int size2 = 0;

    if (1)
    {
        printf("Dequeued from empty: %d\n", dequeue(q2, &front2, size2));
    }
    printf("New front: %d\n", front2);

    return 0;
}

